// Cast rays in different directions and count intersections
// If odd number of intersections, point is inside

int insideCount = 0;

for (int i = 0; i < numberOfChecks; ++i) {
    // Generate ray direction - could use different strategies
    // For example, directions along coordinate axes or random directions

    // CGAL AABB tree intersection
    Ray_3 ray(p, direction);

    std::vector<Object_and_point> intersections;
    tree.all_intersections(ray, std::back_inserter(intersections));

    // Count only intersections that are actually with the mesh (not just touching)
    // For ray casting, we typically count intersections where the ray crosses the surface

    if (intersections.size() % 2 == 1) {
        insideCount++;
    }
}

// Return true if majority of rays indicate inside
return insideCount > numberOfChecks / 2;

